package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.pricing.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.sql.Timestamp; import java.util.*;
@Repository public class JdbcPriceRepository implements PriceRepository { private final JdbcTemplate jdbc; public JdbcPriceRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public Price save(Price p){jdbc.update("INSERT INTO prices(id,tenant_id,sellable_product_id,amount,currency,valid_from,valid_until,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,updated_at=?",p.id(),p.tenantId(),p.sellableProductId(),p.money().amount(),p.money().currency().getCurrencyCode(),Timestamp.from(p.validFrom()),Timestamp.from(p.validUntil()),p.status().name(),Timestamp.from(p.createdAt()),Timestamp.from(p.updatedAt()),p.status().name(),Timestamp.from(p.updatedAt()));return p;}
 private Price map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return Price.rehydrate((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),(UUID)r.getObject("sellable_product_id"),new Money(r.getBigDecimal("amount"),Currency.getInstance(r.getString("currency"))),r.getTimestamp("valid_from").toInstant(),r.getTimestamp("valid_until").toInstant(),PriceStatus.valueOf(r.getString("status")),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
 public Optional<Price> findByTenantIdAndId(UUID t,UUID id){return jdbc.query("SELECT * FROM prices WHERE tenant_id=? AND id=?",this::map,t,id).stream().findFirst();} public List<Price> findAllByTenantIdAndProductId(UUID t,UUID p){return jdbc.query("SELECT * FROM prices WHERE tenant_id=? AND sellable_product_id=? ORDER BY valid_from DESC",this::map,t,p);} public Optional<Price> findActiveByTenantIdAndProductId(UUID t,UUID p){return jdbc.query("SELECT * FROM prices WHERE tenant_id=? AND sellable_product_id=? AND status='ACTIVE' AND valid_from<=CURRENT_TIMESTAMP AND valid_until>CURRENT_TIMESTAMP ORDER BY valid_from DESC",this::map,t,p).stream().findFirst();}
}
